begin;
create extension if not exists pgtap with schema extensions;
set search_path = public,extensions;
select no_plan();
insert into auth.users(id,is_anonymous) values
 ('11111111-1111-4111-8111-111111111111',true),
 ('22222222-2222-4222-8222-222222222222',true);
select ok((select relrowsecurity from pg_class where oid='public.forge_states'::regclass),'state RLS enabled');
select ok((select relrowsecurity from pg_class where oid='public.forge_mutations'::regclass),'mutation RLS enabled');
select ok(not has_table_privilege('anon','public.forge_states','SELECT'),'anon cannot read state');
select ok(not has_table_privilege('anon','public.forge_mutations','SELECT'),'anon cannot read mutations');
select ok(not has_function_privilege('anon','public.commit_forge_state(bigint,uuid,jsonb,jsonb,boolean)','EXECUTE'),'anon cannot commit');
select ok(not has_function_privilege('anon','public.delete_forge_data(bigint)','EXECUTE'),'anon cannot delete');
select ok(not has_table_privilege('anon','public.forge_states','INSERT,UPDATE,DELETE'),'anon cannot mutate state');
select ok(not has_table_privilege('anon','public.forge_mutations','INSERT,UPDATE,DELETE'),'anon cannot mutate log');
set local role authenticated;
select throws_ok($$select public.commit_forge_state(0,'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','{"schemaVersion":1}','[{"eventId":"eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee","at":"2026-10-11T00:00:00.000Z","type":"CONFIRM_FULL_DECK","payload":{}}]')$$,'42501','AUTH_REQUIRED','missing UID denied');
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select is(public.commit_forge_state(0,'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','{"schemaVersion":1}','[{"eventId":"eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee","at":"2026-10-11T00:00:00.000Z","type":"CONFIRM_FULL_DECK","payload":{}}]'),'{"status":"COMMITTED","revision":1}'::jsonb,'A first commit');
select is((select count(*) from public.forge_states),1::bigint,'A reads own state');
select is((select count(*) from public.forge_mutations),1::bigint,'A reads own mutation');
select is(public.commit_forge_state(0,'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','{"schemaVersion":1}','[{"eventId":"eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee","at":"2026-10-11T00:00:00.000Z","type":"CONFIRM_FULL_DECK","payload":{}}]'),'{"status":"COMMITTED","revision":1}'::jsonb,'retry returns original revision');
select is((select count(*) from public.forge_mutations),1::bigint,'retry does not duplicate');
select throws_ok($$select public.commit_forge_state(0,'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','{"schemaVersion":1,"changed":true}','[{"eventId":"eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee","at":"2026-10-11T00:00:00.000Z","type":"CONFIRM_FULL_DECK","payload":{}}]')$$,'22023','MUTATION_ID_REUSED','same ID different state rejected');
select throws_ok($$select public.commit_forge_state(0,'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','{"schemaVersion":1}','[{"eventId":"eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee","at":"2026-10-11T00:00:00.000Z","type":"RECORD_DRAW","payload":{"roundId":"r1","rank":4}}]')$$,'22023','MUTATION_ID_REUSED','same ID different actions rejected');
select is(public.commit_forge_state(0,'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','{"schemaVersion":1}','[{"eventId":"eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee","at":"2026-10-11T00:00:00.000Z","type":"RECORD_DRAW","payload":{"roundId":"r1","rank":4}}]')->>'status','VERSION_CONFLICT','stale revision rejected');
select throws_ok($$insert into public.forge_states(user_id,state) values('22222222-2222-4222-8222-222222222222','{}')$$,'42501',null,'direct insert denied');
select throws_ok($$update public.forge_states set state='{}'$$,'42501',null,'direct update denied');
select throws_ok($$delete from public.forge_states$$,'42501',null,'direct delete denied');
select throws_ok($$insert into public.forge_mutations(user_id,mutation_id,resulting_revision,request_hash,actions) values('11111111-1111-4111-8111-111111111111',gen_random_uuid(),2,'\x00','[]')$$,'42501',null,'direct mutation insert denied');
select throws_ok($$update public.forge_mutations set actions='[]'$$,'42501',null,'direct mutation update denied');
select throws_ok($$delete from public.forge_mutations$$,'42501',null,'direct mutation delete denied');
select throws_ok($$select public.commit_forge_state(1,gen_random_uuid(),'[]','[{"eventId":"eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee","at":"2026-10-11T00:00:00.000Z","type":"RECORD_DRAW","payload":{"roundId":"r1","rank":4}}]')$$,'22023','INVALID_STATE','state must be object');
select throws_ok($$select public.commit_forge_state(1,gen_random_uuid(),'{"schemaVersion":2}','[{"eventId":"eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee","at":"2026-10-11T00:00:00.000Z","type":"RECORD_DRAW","payload":{"roundId":"r1","rank":4}}]')$$,'22023','INVALID_STATE','unsupported version rejected');
select throws_ok($$select public.commit_forge_state(1,gen_random_uuid(),jsonb_build_object('schemaVersion',1,'data',repeat('x',524288)),'[{"eventId":"eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee","at":"2026-10-11T00:00:00.000Z","type":"RECORD_DRAW","payload":{"roundId":"r1","rank":4}}]')$$,'22023','INVALID_STATE','oversized state rejected');
select throws_ok($$select public.commit_forge_state(1,gen_random_uuid(),'{"schemaVersion":1}','{}')$$,'22023','INVALID_ACTIONS','actions must be array');
select throws_ok($$select public.commit_forge_state(1,gen_random_uuid(),'{"schemaVersion":1}','[{"type":"UNKNOWN"}]')$$,'22023','INVALID_ACTIONS','unknown action rejected');
select throws_ok($$select public.commit_forge_state(1,gen_random_uuid(),'{"schemaVersion":1}','[{}]')$$,'22023','INVALID_ACTIONS','missing type rejected');
select throws_ok($$select public.commit_forge_state(1,gen_random_uuid(),'{"schemaVersion":1}','[{"type":"CONFIRM_FULL_DECK"}]')$$,'22023','INVALID_ACTIONS','missing event envelope rejected');
select throws_ok($$select public.commit_forge_state(1,gen_random_uuid(),'{"schemaVersion":1}','[{"eventId":"not-uuid","at":"2026-10-11T00:00:00.000Z","type":"CONFIRM_FULL_DECK","payload":{}}]')$$,'22023','INVALID_ACTIONS','invalid event ID rejected');
select throws_ok($$select public.commit_forge_state(1,gen_random_uuid(),'{"schemaVersion":1}','[{"eventId":"eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee","at":"2026-02-30T00:00:00.000Z","type":"CONFIRM_FULL_DECK","payload":{}}]')$$,'22023','INVALID_ACTIONS','impossible event date rejected');
select throws_ok($$select public.commit_forge_state(1,gen_random_uuid(),'{"schemaVersion":1}','[{"eventId":"eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee","at":"2026-10-11T00:00:00.000Z","type":"CONFIRM_FULL_DECK"}]')$$,'22023','INVALID_ACTIONS','missing payload rejected');
select throws_ok($$select public.commit_forge_state(1,gen_random_uuid(),'{"schemaVersion":1}',(select jsonb_agg(jsonb_build_object('type','RECORD_DRAW')) from generate_series(1,201)))$$,'22023','INVALID_ACTIONS','batch over 200 rejected');
select throws_ok($$select public.commit_forge_state(1,gen_random_uuid(),'{"schemaVersion":1}',jsonb_build_array(jsonb_build_object('type','RECORD_DRAW','payload',repeat('x',524288))))$$,'22023','INVALID_ACTIONS','oversized actions rejected');
select throws_ok($$select public.commit_forge_state(null,gen_random_uuid(),'{"schemaVersion":1}','[{"eventId":"eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee","at":"2026-10-11T00:00:00.000Z","type":"RECORD_DRAW","payload":{"roundId":"r1","rank":4}}]')$$,'22023','INVALID_REQUEST','null revision rejected');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
select is((select count(*) from public.forge_states),0::bigint,'B cannot read A state');
select is((select count(*) from public.forge_mutations),0::bigint,'B cannot read A mutations');
select is(public.commit_forge_state(0,'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','{"schemaVersion":1}','[{"eventId":"eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee","at":"2026-10-11T00:00:00.000Z","type":"CONFIRM_FULL_DECK","payload":{}}]')->>'revision','1','B uses same mutation ID independently');
select is(public.delete_forge_data(1)->>'revision','2','B deletes only own data');
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select is((select revision from public.forge_states),1::bigint,'B delete preserved A');
select is(public.delete_forge_data(0)->>'status','VERSION_CONFLICT','stale delete refused');
select is(public.delete_forge_data(1),'{"status":"DELETED","revision":2}'::jsonb,'delete increments revision');
select is((select state from public.forge_states),'{}'::jsonb,'history erased');
select ok((select deleted_at is not null from public.forge_states),'tombstone retained');
select is((select count(*) from public.forge_mutations),0::bigint,'mutation history erased');
select is(public.commit_forge_state(0,'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','{"schemaVersion":1}','[{"eventId":"eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee","at":"2026-10-11T00:00:00.000Z","type":"CONFIRM_FULL_DECK","payload":{}}]')->>'status','VERSION_CONFLICT','old retry cannot resurrect after delete');
select is(public.commit_forge_state(2,'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','{"schemaVersion":1}','[{"eventId":"eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee","at":"2026-10-11T00:00:00.000Z","type":"CONFIRM_FULL_DECK","payload":{}}]')->>'status','DATA_DELETED','new revision requires explicit revive');
select is(public.commit_forge_state(2,'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','{"schemaVersion":1}','[{"eventId":"eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee","at":"2026-10-11T00:00:00.000Z","type":"CONFIRM_FULL_DECK","payload":{}}]',true)->>'revision','3','explicit revive with current revision');
select ok((select deleted_at is null from public.forge_states),'revive clears tombstone');
reset role;
select * from finish();
rollback;
